  const take = () => tokens[position++];
  const is = value => current().value === value;
  const expect = value => {
    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });
  const isComparison = value => value === '<' || value === '<=' ||
    value === '>' || value === '>=' || value === '==' || value === '!=';

  function comparison() {
    const left = sum();
    if (!isComparison(current().value)) return left;
    const operands = [left];
    const operators = [];
    do {
      operators.push(take());
      operands.push(sum());
    } while (isComparison(current().value));
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (is('*') || is('/') || is('//') || is('%')) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  function unary() {
    if (is('+') || is('-')) {
      return { type: 'unary', operator: take(), operand: unary() };
    }
    return power();
  }

  function power() {
    const left = primary();
    if (!is('**')) return left;
    const operator = take();
    return binary(operator, left, unary());
  }

  function primary() {
    const token = take();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'identifier') {
      if (!is('(')) return { type: 'variable', name: token.value, column: token.column };
      take();
      const args = [];
      if (!is(')')) {
        args.push(comparison());
        while (is(',')) {
          take();
          args.push(comparison());
        }
      }
      expect(')');
      if (token.value !== 'min' && token.value !== 'max' && token.value !== 'abs') {
        throw new ExprError('Unknown function', token.column);
